parameters.jsCode:
// Look for the first .xml attachment on the email and carry it forward
// together with the sender details we need later for notifications.
const attachments = $input.item.binary ?? {};
const xmlKey = Object.keys(attachments).find((key) =>
  (attachments[key].fileName ?? '').toLowerCase().endsWith('.xml')
);

return {
  json: {
    xmlKey: xmlKey ?? null,
    sender: $json.from,
    subject: $json.subject,
    receivedAt: $json.date,
  },
  binary: attachments,
};

// Turn the raw UBL XML into a flat, readable invoice object.
// Field names follow the EN 16931 business terms (BT-*) where possible.
const raw = $input.first().json;
if (!raw || Object.keys(raw).length === 0) {
  throw new Error('The file is empty or not valid XML.');
}

// Drop namespace prefixes: "cbc:ID" becomes "ID"
const strip = (value) => {
  if (Array.isArray(value)) return value.map(strip);
  if (value && typeof value === 'object') {
    const out = {};
    for (const [key, val] of Object.entries(value)) out[key.split(':').pop()] = strip(val);
    return out;
  }
  return value;
};

const doc = strip(raw);
const inv = doc.Invoice;
if (!inv) {
  throw new Error('No Invoice element found. UBL is expected - CII/ZUGFeRD is not supported.');
}

// Helpers for the deeply nested XML-to-JSON output
const txt = (value) => {
  if (value === undefined || value === null) return null;
  if (Array.isArray(value)) return txt(value[0]);
  if (typeof value === 'object') return value._ ?? null;
  return String(value);
};
const num = (value) => { const t = txt(value); return t === null ? null : parseFloat(t); };
const list = (value) => (value == null ? [] : Array.isArray(value) ? value : [value]);
const one = (value) => list(value)[0] ?? {};

const sellerParty = one(one(inv.AccountingSupplierParty).Party);
const buyerParty = one(one(inv.AccountingCustomerParty).Party);

// BT-27 / BT-44: registered company name, falling back to trading name
const partyName = (party) =>
  txt(one(party.PartyLegalEntity).RegistrationName) ?? txt(one(party.PartyName).Name);

// BT-31: there are often two entries (VAT ID and tax number) - we want VAT
const vatId = (party) => {
  const schemes = list(party.PartyTaxScheme);
  const vat = schemes.find((s) => txt(one(s.TaxScheme).ID) === 'VAT');
  return txt((vat ?? schemes[0] ?? {}).CompanyID);
};

const totals = one(inv.LegalMonetaryTotal);
const taxTotal = one(inv.TaxTotal);
const payment = one(inv.PaymentMeans);
const address = one(sellerParty.PostalAddress);
const period = one(inv.InvoicePeriod);
const paymentTerms = one(inv.PaymentTerms);

const taxes = list(taxTotal.TaxSubtotal).map((s) => ({
  category: txt(one(s.TaxCategory).ID),
  rate: num(one(s.TaxCategory).Percent),
  netAmount: num(s.TaxableAmount),
  taxAmount: num(s.TaxAmount),
}));

const lines = list(inv.InvoiceLine).map((line) => ({
  position: txt(line.ID),
  description: txt(one(line.Item).Name),
  quantity: num(line.InvoicedQuantity),
  unit: one(line.InvoicedQuantity).unitCode ?? null,
  unitPrice: num(one(line.Price).PriceAmount),
  lineTotal: num(line.LineExtensionAmount),
}));

// Document level allowances and charges
const allowancesCharges = list(inv.AllowanceCharge).map((entry) => ({
  isCharge: txt(entry.ChargeIndicator) === 'true',
  reason: txt(entry.AllowanceChargeReason),
  amount: num(entry.Amount),
  rate: num(one(entry.TaxCategory).Percent),
}));

return [{ json: {
  invoiceNumber: txt(inv.ID),
  invoiceDate: txt(inv.IssueDate),
  dueDate: txt(inv.DueDate),
  invoiceTypeCode: txt(inv.InvoiceTypeCode),
  currency: txt(inv.DocumentCurrencyCode),
  buyerReference: txt(inv.BuyerReference),
  orderReference: txt(one(inv.OrderReference).ID),
  deliveryDate: txt(one(inv.Delivery).ActualDeliveryDate),
  notes: list(inv.Note).map(txt),
  servicePeriod: { from: txt(period.StartDate), to: txt(period.EndDate) },
  paymentTerms: txt(paymentTerms.Note),
  precedingInvoices: list(inv.BillingReference).map((b) => txt(one(b.InvoiceDocumentReference).ID)),
  allowanceTotal: num(totals.AllowanceTotalAmount),
  chargeTotal: num(totals.ChargeTotalAmount),
  prepaidAmount: num(totals.PrepaidAmount),
  rounding: num(totals.PayableRoundingAmount),
  seller: {
    name: partyName(sellerParty),
    vatId: vatId(sellerParty),
    postalCode: txt(address.PostalZone),
    city: txt(address.CityName),
    country: txt(one(address.Country).IdentificationCode),
  },
  buyer: {
    name: partyName(buyerParty),
  },
  payment: {
    meansCode: txt(payment.PaymentMeansCode),
    iban: txt(one(payment.PayeeFinancialAccount).ID),
    accountHolder: txt(one(payment.PayeeFinancialAccount).Name),
  },
  lineTotal: num(totals.LineExtensionAmount),
  netAmount: num(totals.TaxExclusiveAmount),
  taxAmount: num(taxTotal.TaxAmount),
  grossAmount: num(totals.TaxInclusiveAmount),
  payableAmount: num(totals.PayableAmount),
  taxes,
  allowancesCharges,
  lines,
} }];

// Check the parsed invoice for missing mandatory fields and for totals
// that do not add up. Errors mark the invoice invalid, warnings do not.
const inv = $input.first().json;
const errors = [];
const warnings = [];

const round = (n) => Math.round((n ?? 0) * 100) / 100;
const equal = (a, b) => Math.abs(round(a) - round(b)) < 0.01;

// Mandatory fields per EN 16931
const mandatory = {
  invoiceNumber: 'BT-1 Invoice number',
  invoiceDate: 'BT-2 Invoice issue date',
  currency: 'BT-5 Invoice currency code',
  invoiceTypeCode: 'BT-3 Invoice type code',
};
for (const [field, label] of Object.entries(mandatory)) {
  if (!inv[field]) errors.push(`Missing mandatory field: ${label}`);
}
if (!inv.seller?.name) errors.push('Missing mandatory field: BT-27 Seller name');
if (!inv.buyer?.name) errors.push('Missing mandatory field: BT-44 Buyer name');
if (!inv.seller?.vatId) warnings.push('No seller VAT identifier (BT-31)');

// Arithmetic checks
const lineSum = inv.lines.reduce((sum, line) => sum + (line.lineTotal ?? 0), 0);
const sum = (arr) => arr.reduce((total, entry) => total + (entry.amount ?? 0), 0);

const allowances = inv.allowanceTotal ?? sum(inv.allowancesCharges.filter((a) => !a.isCharge));
const charges = inv.chargeTotal ?? sum(inv.allowancesCharges.filter((a) => a.isCharge));

const expectedNet = lineSum - allowances + charges;
if (!equal(expectedNet, inv.netAmount)) {
  errors.push(
    `Lines ${round(lineSum)} - allowances ${round(allowances)} + charges ${round(charges)} = ` +
    `${round(expectedNet)}, but the stated net amount is ${round(inv.netAmount)}`
  );
}

const taxSum = inv.taxes.reduce((total, tax) => total + (tax.taxAmount ?? 0), 0);
if (!equal(taxSum, inv.taxAmount)) {
  errors.push(`Tax breakdown ${round(taxSum)} does not match stated tax ${round(inv.taxAmount)}`);
}

if (!equal(inv.netAmount + inv.taxAmount, inv.grossAmount)) {
  errors.push(
    `Net ${round(inv.netAmount)} + tax ${round(inv.taxAmount)} does not equal gross ${round(inv.grossAmount)}`
  );
}

const expectedPayable = inv.grossAmount - (inv.prepaidAmount ?? 0) + (inv.rounding ?? 0);
if (!equal(expectedPayable, inv.payableAmount)) {
  errors.push(
    `Gross ${round(inv.grossAmount)} - prepaid ${round(inv.prepaidAmount ?? 0)} = ` +
    `${round(expectedPayable)}, but the stated payable amount is ${round(inv.payableAmount)}`
  );
}

// Tax rates - adjust ALLOWED_RATES to the rates used in your country
const ALLOWED_RATES = [0, 7, 19];
inv.taxes.forEach((tax) => {
  if (!ALLOWED_RATES.includes(tax.rate)) {
    warnings.push(`Unusual tax rate: ${tax.rate}%`);
  }
  if (tax.rate != null && !equal((tax.netAmount * tax.rate) / 100, tax.taxAmount)) {
    errors.push(
      `At ${tax.rate}%: expected ${round((tax.netAmount * tax.rate) / 100)}, stated ${round(tax.taxAmount)}`
    );
  }
});

// Line level plausibility
inv.lines.forEach((line) => {
  if (line.quantity != null && line.unitPrice != null &&
      !equal(line.quantity * line.unitPrice, line.lineTotal)) {
    warnings.push(
      `Line ${line.position}: ${line.quantity} x ${line.unitPrice} does not equal ${line.lineTotal}`
    );
  }
});

// Date formats
const isDate = (value) => /^\d{4}-\d{2}-\d{2}$/.test(value ?? '');
if (inv.invoiceDate && !isDate(inv.invoiceDate)) {
  errors.push('Invoice date is not in YYYY-MM-DD format');
}
if (isDate(inv.dueDate) && isDate(inv.invoiceDate) && inv.dueDate < inv.invoiceDate) {
  errors.push('Due date is earlier than the invoice date');
}

return [{ json: {
  ...inv,
  validation: {
    isValid: errors.length === 0,
    errors,
    warnings,
    checkedAt: new Date().toISOString(),
  },
} }];

// Rebuild a binary item so the original XML can be written to disk
// under a readable, sortable file name.
const source = $('Find XML Attachment').item;
const safeNumber = ($json.invoiceNumber ?? 'unknown').replace(/[^\w.-]/g, '_');

return {
  json: {
    ...$json,
    fileName: `${$json.invoiceDate ?? 'no-date'}_${safeNumber}.xml`,
    sender: source.json.sender,
    subject: source.json.subject,
  },
  binary: { invoice: source.binary[source.json.xmlKey] },
};

// Rebuild a binary item so the original XML can be written to disk
// under a readable, sortable file name.
const source = $('Find XML Attachment').item;
const safeNumber = ($json.invoiceNumber ?? 'unknown').replace(/[^\w.-]/g, '_');

return {
  json: {
    ...$json,
    fileName: `${$json.invoiceDate ?? 'no-date'}_${safeNumber}.xml`,
    sender: source.json.sender,
    subject: source.json.subject,
  },
  binary: { invoice: source.binary[source.json.xmlKey] },
};

