// Reached when the XML cannot be parsed at all. Collect just enough
// context so accounting can chase the invoice manually.
const source = $('Find XML Attachment').first();

return {
  json: {
    sender: source.json.sender,
    subject: source.json.subject,
    file: source.json.xmlKey,
    reason:
      $json.error?.message ??
      $json.error?.description ??
      $json.message ??
      'File could not be processed',
  },
};

